/* Catalog-backed NPC services; uses the imported engine through an atomic save adapter. */
(function(){'use strict';const E=DecideLegacyEconomy,A=DecideCatalogEconomy,box=document.createElement('details');box.id='catalogServices';box.className='adventure-panel';const summary=document.createElement('summary');summary.textContent='ร้านค้า คลังไอเท็ม และปรุงยา';const body=document.createElement('div');box.append(summary,body);$('characterPanel').before(box);
let npcId='',selectedBuy='',message='';const reasons={NPC_NOT_FOUND:'ไม่พบผู้ให้บริการ',ITEM_NOT_FOUND:'ไม่พบไอเท็ม',ITEM_NOT_IN_STOCK:'NPC คนนี้ไม่มีสินค้าชิ้นนี้',ITEM_NOT_FOR_SALE:'รายการนี้ยังไม่ได้ตั้งราคาขาย',INSUFFICIENT_GOLD:'เหรียญไม่พอ',NOT_OWNED_ENOUGH:'ของในคลังไม่พอ',ITEM_NOT_SELLABLE:'รายการนี้ยังไม่มีราคาขายคืน',PROVIDER_NOT_ALLOWED:'NPC คนนี้ไม่ได้ให้บริการสูตรนี้',RESULT_ITEM_NOT_FOUND:'ไม่พบไอเท็มผลลัพธ์ที่เปิดใช้งาน',INGREDIENTS_INSUFFICIENT:'วัตถุดิบไม่ครบ',ITEM_UNSUPPORTED_EFFECT:'ไอเท็มนี้ยังไม่มีผลใช้งานที่รองรับ'};
const text=(tag,value,parent=body)=>{const el=document.createElement(tag);el.textContent=value;parent.append(el);return el;};function button(label,fn,parent=body){const b=text('button',label,parent);b.type='button';b.onclick=fn;return b;}
function run(fn){try{const result=fn();s=result.snapshot;save();render();message='ทำรายการและบันทึกแล้ว';}catch(e){message=reasons[e.message]||e.message;}draw();}
function draw(){if(!box.open)return;body.replaceChildren();if(!s.character){text('p','สร้างหรือโหลดตัวละครก่อน');return;}const rows=R.records(DB),allNpc=rows.filter(r=>r.kind==='npc'&&r.enabled!==false),recipes=rows.filter(r=>r.kind==='recipe'&&r.enabled!==false),providers=allNpc.filter(n=>n.items?.length||recipes.some(r=>r.providerNpcIds?.includes(n.id)));if(!providers.some(n=>n.id===npcId))npcId=providers[0]?.id||'';const npc=providers.find(n=>n.id===npcId);text('p','เหรียญ '+s.gold+' · บริการตามรายการสินค้าและสูตรในฐานข้อมูล');text('p','ไอเท็มฟื้นฟูใช้ได้ที่หน้านี้ หรือในสนามกับสมาชิกที่สั่งการโดยใช้ 1 AP • อุปกรณ์ที่ซื้อเก็บในคลัง เลือกใส่ได้ที่หน้าต่างอุปกรณ์สวมใส่');const notice=text('p',message);notice.id='catalogServiceStatus';notice.setAttribute('role','status');const label=text('label','ผู้ให้บริการ'),select=document.createElement('select');select.id='catalogNpc';for(const n of providers)select.add(new Option(n.displayName||n.name,n.id));select.value=npcId;select.onchange=()=>{npcId=select.value;message='';draw();};label.append(select);if(!npc)return;
const stock=rows.filter(r=>E.PRICEABLE_CONTENT_TYPES.includes(r.kind)&&r.enabled!==false&&Number(r.buyPrice)>0&&npc.items?.includes(r.name));text('h3','ซื้อสินค้า');if(!stock.length)text('p','ไม่มีสินค้าที่ตั้งราคาขาย');else{const shop=document.createElement('select');shop.id='catalogBuyChoice';for(const r of stock){const q=E.checkShopPurchase(npc,r,1,s.gold,r.buyPrice);shop.add(new Option((r.displayName||r.name)+' · '+(q.ok?q.unitPrice:Math.round(Number(r.buyPrice)))+' เหรียญ',r.key));}if(stock.some(r=>r.key===selectedBuy))shop.value=selectedBuy;shop.onchange=()=>selectedBuy=shop.value;body.append(shop);button('ซื้อ 1 ชิ้น',()=>{selectedBuy=shop.value;const item=stock.find(r=>r.key===shop.value);run(()=>A.buy(s,R.records(DB),npcId,item.kind,item.id));}).id='catalogBuy';}
text('h3','คลังไอเท็ม');const party=A.party(s),items=E.getArenaPartyInventory(party);if(!items.length)text('p','ยังไม่มีไอเท็มในคลังนี้');for(const entry of items){const line=text('div',''),candidates=rows.filter(r=>['item','dropItem'].includes(r.kind)&&r.name===entry.name&&r.enabled!==false);text('span',entry.name+' ×'+entry.quantity+' ',line);if(candidates.length!==1){text('small','ไม่พบรายการเดียวที่ระบุชนิดได้แน่นอน',line);continue;}const item=candidates[0];line.dataset.catalogItem=item.id;if(item.kind==='item'){const use=button('ใช้ 1 ชิ้น',()=>run(()=>A.use(s,R.records(DB),item.id)),line);use.disabled=!['heal_hp','restore_mp'].includes(item.effectType);}const quote=E.checkSellOffer(npc,item,item.kind,1,party,'inventory','hero');if(quote.ok)button('ขาย 1 ชิ้น · '+quote.unitPrice+' เหรียญ',()=>run(()=>A.sell(s,R.records(DB),npcId,item.kind,item.id)),line);}
const gear=E.getArenaPartyGearStash(party);if(gear.length){text('h3','อุปกรณ์สำรองจากฐานข้อมูล');for(const entry of gear){const line=text('div',entry.name+' ×'+entry.quantity+' '),item=rows.find(r=>r.kind===entry.refType&&r.name===entry.name&&r.enabled!==false);if(item)button('ขายคืน 1 ชิ้น',()=>run(()=>A.sell(s,R.records(DB),npcId,item.kind,item.id)),line);}}
text('h3','ปรุงยา');const offered=recipes.filter(r=>!r.providerNpcIds?.length||r.providerNpcIds.includes(npc.id));if(!offered.length)text('p','ผู้ให้บริการคนนี้ไม่มีสูตร');for(const recipe of offered){const row=text('article','');text('strong',recipe.displayName||recipe.name,row);const check=E.checkCraftRequirements(recipe,npc,party,s.gold,rows.filter(r=>r.kind==='item'));text('p',(recipe.ingredients||[]).map(kv=>kv.key+' ×'+kv.value).join(' + ')+' → '+recipe.resultItemName+' ×'+recipe.resultQuantity+' · '+recipe.goldCost+' เหรียญ',row);text('small',check.ok?'วัตถุดิบและเหรียญครบ':reasons[check.reason]||check.reason,row);button('ปรุง',()=>run(()=>A.craft(s,R.records(DB),npcId,recipe.id)),row);}
for(const b of body.querySelectorAll('button'))if(s.expedition||s.dead||s.event)b.disabled=true;
}
box.addEventListener('toggle',draw);window.DecideCatalogServices={refresh:draw};
})();
